/**
 * Payment Integration Plugin
 * Backward-compatible payment processing with multiple providers
 * Built-in plugin for GSM Flow
 */

import { definePlugin, EXTENSION_POINTS, type PluginContext } from '@gsmflow/plugin-sdk';

export default definePlugin({
	id: 'payment-core',
	name: 'Payment Core',
	version: '1.0.0',
	permissions: ['db.read', 'db.write', 'payment.process'],

	setup(registry) {
		// Register payment methods
		registry.register(EXTENSION_POINTS.CHECKOUT.PAYMENT, {
			priority: 1,
			handler: async (_context: PluginContext, data: unknown) => {
				const paymentData = data as {
					method: string;
					amount: number;
					currency: string;
					metadata?: Record<string, unknown>;
				};

				switch (paymentData.method) {
					case 'balance':
						return await processBalancePayment(_context, paymentData);
					case 'stripe':
						return await processStripePayment(_context, paymentData);
					case 'paypal':
						return await processPayPalPayment(_context, paymentData);
					default:
						throw new Error(`Unsupported payment method: ${paymentData.method}`);
				}
			}
		});

		// Register checkout methods
		registry.register(EXTENSION_POINTS.CHECKOUT.METHOD, {
			priority: 1,
			handler: async (_context: PluginContext) => {
				return {
					methods: [
						{
							id: 'balance',
							name: 'Account Balance',
							description: 'Pay using your account balance',
							enabled: true,
							requiresSetup: false
						},
						{
							id: 'stripe',
							name: 'Credit Card',
							description: 'Pay with credit or debit card',
							enabled: await isStripeEnabled(_context),
							requiresSetup: true
						},
						{
							id: 'paypal',
							name: 'PayPal',
							description: 'Pay with PayPal',
							enabled: await isPayPalEnabled(_context),
							requiresSetup: true
						}
					]
				};
			}
		});

		// Register billing webhooks
		registry.register(EXTENSION_POINTS.BILLING.WEBHOOK, {
			priority: 1,
			handler: async (_context: PluginContext, data: unknown) => {
				const webhookData = data as {
					provider: string;
					event: string;
					payload: Record<string, unknown>;
				};

				switch (webhookData.provider) {
					case 'stripe':
						return await handleStripeWebhook(_context, webhookData);
					case 'paypal':
						return await handlePayPalWebhook(_context, webhookData);
					default:
						_context.log.warn(`Unknown webhook provider: ${webhookData.provider}`);
						return null;
				}
			}
		});

		// Register invoice generator
		registry.register(EXTENSION_POINTS.INVOICE.GENERATOR, {
			priority: 1,
			handler: async (_context: PluginContext, data: unknown) => {
				const invoiceData = data as {
					orderId: string;
					userId: string;
					items: Array<{
						name: string;
						quantity: number;
						price: number;
					}>;
				};

				return await generateInvoice(_context, invoiceData);
			}
		});

		// Register admin sidebar item
		registry.register(EXTENSION_POINTS.ADMIN.SIDEBAR_ITEM, {
			priority: 2,
			handler: async (_context: PluginContext) => {
				return {
					id: 'payments',
					label: 'Payments',
					href: '/admin/payments',
					children: [
						{
							id: 'payments-transactions',
							label: 'Transactions',
							href: '/admin/payments/transactions'
						},
						{
							id: 'payments-methods',
							label: 'Payment Methods',
							href: '/admin/payments/methods'
						},
						{
							id: 'payments-invoices',
							label: 'Invoices',
							href: '/admin/payments/invoices'
						}
					]
				};
			}
		});
	},

	async onInstall(_context: PluginContext) {
		_context.log.info('Payment plugin installed');

		// Create payment settings
		if (_context.hasPermission('db.write')) {
			try {
				await _context.db.execute(
					`INSERT OR IGNORE INTO settings (key, value, created_at, updated_at) 
					 VALUES (?, ?, ?, ?)`,
					[
						'payment_methods',
						JSON.stringify({
							balance: { enabled: true },
							stripe: { enabled: false, publicKey: '', secretKey: '' },
							paypal: { enabled: false, clientId: '', clientSecret: '' }
						}),
						new Date().toISOString(),
						new Date().toISOString()
					]
				);

				_context.log.info('Created payment settings');
			} catch (err) {
				_context.log.error('Failed to create payment settings', {
					error: err instanceof Error ? err.message : String(err)
				});
			}
		}
	},

	async onEnable(_context: PluginContext) {
		_context.log.info('Payment plugin enabled');
	},

	async onDisable(_context: PluginContext) {
		_context.log.info('Payment plugin disabled');
	},

	async onUninstall(_context: PluginContext) {
		_context.log.info('Payment plugin uninstalled');
	}
});

// ========================================
// PAYMENT PROCESSORS
// ========================================

async function processBalancePayment(
	_context: PluginContext,
	data: {
		amount: number;
		currency: string;
		metadata?: Record<string, unknown>;
	}
): Promise<{ success: boolean; transactionId?: string; error?: string }> {
	if (!_context.user) {
		return { success: false, error: 'User not authenticated' };
	}

	if (!_context.hasPermission('payment.process')) {
		return { success: false, error: 'Permission denied' };
	}

	try {
		// Check user balance
		const userResult = await _context.db.query<{ balance: string }>(
			'SELECT balance FROM users WHERE id = ? LIMIT 1',
			[_context.user.id]
		);

		if (!userResult[0]) {
			return { success: false, error: 'User not found' };
		}

		const balance = parseFloat(userResult[0].balance);
		if (balance < data.amount) {
			return { success: false, error: 'Insufficient balance' };
		}

		// Deduct balance
		await _context.db.execute(
			'UPDATE users SET balance = balance - ? WHERE id = ?',
			[data.amount, _context.user.id]
		);

		// Create transaction record
		const transactionId = `txn_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
		await _context.db.execute(
			`INSERT INTO balance_transactions 
			 (id, user_id, type, amount, balance_after, description, created_at) 
			 VALUES (?, ?, ?, ?, ?, ?, ?)`,
			[
				transactionId,
				_context.user.id,
				'debit',
				data.amount,
				balance - data.amount,
				data.metadata?.description || 'Payment',
				new Date().toISOString()
			]
		);

		_context.log.info('Balance payment processed', {
			userId: _context.user.id,
			amount: data.amount,
			transactionId
		});

		return { success: true, transactionId };
	} catch (err) {
		_context.log.error('Balance payment failed', {
			error: err instanceof Error ? err.message : String(err)
		});
		return { success: false, error: 'Payment processing failed' };
	}
}

