// ========================================
// PAYMENT METHOD CHECKS
// ========================================

async function isStripeEnabled(_context: PluginContext): Promise<boolean> {
	if (!_context.hasPermission('db.read')) {
		return false;
	}

	try {
		const result = await _context.db.query<{ value: string }>(
			"SELECT value FROM settings WHERE key = 'payment_methods' LIMIT 1"
		);

		if (!result[0]) {
			return false;
		}

		const settings = JSON.parse(result[0].value);
		return settings.stripe?.enabled === true;
	} catch {
		return false;
	}
}

async function isPayPalEnabled(_context: PluginContext): Promise<boolean> {
	if (!_context.hasPermission('db.read')) {
		return false;
	}

	try {
		const result = await _context.db.query<{ value: string }>(
			"SELECT value FROM settings WHERE key = 'payment_methods' LIMIT 1"
		);

		if (!result[0]) {
			return false;
		}

		const settings = JSON.parse(result[0].value);
		return settings.paypal?.enabled === true;
	} catch {
		return false;
	}
}

